UPDATE mall_seckill_activity
product_id = #{productId}, sku_id = #{skuId}, activity_name = #{activityName}, original_price = #{originalPrice}, seckill_price = #{seckillPrice}, seckill_stock = #{seckillStock}, available_stock = #{availableStock}, limit_per_user = #{limitPerUser}, start_time = #{startTime}, end_time = #{endTime}, allow_restock = #{allowRestock}, updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}

UPDATE mall_seckill_activity
SET status = 0, updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}

UPDATE mall_seckill_activity
SET available_stock = available_stock - #{quantity},
    updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}
  AND available_stock >= #{quantity}
